/* ONE LIVERY SYSTEM, NOT TWO.
 *
 * For most of this project's life the word livery named two unrelated things:
 *
 *   the APP's   — sky / amber / tarmac / beacon / runway / skydrol, chosen in
 *                 Appearance, generated by src/lib/liveryEngine.js, written to
 *                 documentElement as data-livery. This is the design system.
 *
 *   the PILOT's — dawn-patrol / night-ops / contrail / carrier-deck /
 *                 altimeter, chosen once during signup, stored on the profile,
 *                 and used to tint that person's tail.
 *
 * The second one was removed on 2026-09-04. It had already stopped painting
 * anything — every --tail-<id> token in app.css resolved to var(--active), for
 * all twelve ids across both sets — so what remained was a step in onboarding
 * asking a new student to choose between six swatches that produce the same
 * colour, and a settings row doing the same.
 *
 * This exists because the two are easy to confuse and the dead one is easy to
 * reintroduce: a `livery` on a profile row reads like something that ought to
 * be rendered. It is not. A person carries no colour of their own here.
 *
 * Run: npm run check:one-livery
 */
import { readFileSync, readdirSync, statSync, existsSync } from "node:fs";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = fileURLToPath(new URL("..", import.meta.url));
const SRC = join(ROOT, "src");

// aurora is deliberately absent: it is a live FINISH id in liveryEngine.
const RETIRED_IDS = ["dawn-patrol", "night-ops", "carrier-deck", "contrail", "altimeter"];
const GONE = ["src/lib/liveries.js", "src/components/LiveryPicker.jsx"];

const walk = (dir) => readdirSync(dir).flatMap((e) => {
  const p = join(dir, e);
  return statSync(p).isDirectory() ? walk(p) : [p];
});

// Comments are where the removal is DESCRIBED, so they must not be searched —
// this script's own prose would fail it otherwise, and a previous checker in
// this repo did exactly that.
const strip = (s) => s
  .replace(/\/\*[\s\S]*?\*\//g, "")
  .replace(/(^|[^:])\/\/.*$/gm, "$1");

const fails = [];
let scanned = 0;

for (const f of GONE) {
  if (existsSync(join(ROOT, f))) fails.push(`${f} is back. It was the old build's pilot-livery system.`);
}

for (const path of walk(SRC).filter((p) => /\.(js|jsx|css)$/.test(p))) {
  const rel = relative(ROOT, path);
  const code = strip(readFileSync(path, "utf8"));
  scanned++;

  // liveryEngine is the one legitimate mention: the APP's liveries were once
  // named dawn-patrol, night-ops and the rest too, and it still translates a
  // stored id from that era into a current one. That map is a migration, not
  // the pilot system, and it has to keep working.
  if (!rel.endsWith("liveryEngine.js")) {
    for (const id of RETIRED_IDS) {
      if (code.includes(id)) fails.push(`${rel} names the retired pilot livery "${id}".`);
    }
  }
  if (/from\s+["'][^"']*\/liveries\.js["']/.test(code)) fails.push(`${rel} imports lib/liveries.js.`);
  if (/LiveryPicker/.test(code)) fails.push(`${rel} references LiveryPicker.`);

  // --tail-ink and --tail-bg are the whole set. Anything else is a per-person
  // colour token, which is the thing that turned out to mean nothing.
  for (const m of code.matchAll(/--tail-([a-z-]+)/g)) {
    if (m[1] !== "ink" && m[1] !== "bg") fails.push(`${rel} uses --tail-${m[1]}, a per-livery tail token.`);
  }

  // A profile's livery column is gone from the database in 0013; reading one
  // back would silently be undefined rather than fail.
  if (/\.livery\b/.test(code) && !rel.endsWith("liveryEngine.js")) {
    fails.push(`${rel} reads .livery off a row.`);
  }
  // Only on Tail. App.jsx and Profile.jsx pass livery={shownLivery} around all
  // day and that is the app's, which is fine.
  if (/<Tail\b[^>]*\slivery=/.test(code)) {
    fails.push(`${rel} passes a livery prop to Tail. Tail takes none.`);
  }
}

if (fails.length) {
  console.log("one-livery: FAIL\n");
  for (const f of fails) console.log(`  ${f}`);
  process.exit(1);
}

console.log(`one-livery: ${scanned} source files scanned`);
console.log(`  no trace of the retired pilot livery — ${RETIRED_IDS.length} ids, 2 deleted modules,`);
console.log("  the per-person tail tokens, and the prop that carried it");
